"""Unsupervised Drift Detector computing Input PSI, Entropy Shift, and Action Shift."""

from __future__ import annotations
import json
from pathlib import Path
from typing import Any
import numpy as np
from pydantic import BaseModel, Field

from rl_ide.contracts.adapter import EpisodeLog


class DriftReport(BaseModel):
    """Report generated by inspecting live inference data against drift baseline."""
    is_drifted: bool
    max_psi: float
    psi_per_feature: dict[str, float] = Field(default_factory=dict)
    entropy_zscore: float
    current_entropy: float
    action_shift_zscore: float
    current_action_dist: dict[str, float] = Field(default_factory=dict)
    reasons: list[str] = Field(default_factory=list)
    recommendation: str = "Policy confident, no drift detected."


class DriftBaseline(BaseModel):
    """Baseline metrics computed from training episodes."""
    feature_names: list[str]
    quantiles_per_feature: dict[str, list[float]]
    expected_proportions: dict[str, list[float]] = Field(default_factory=dict)
    entropy_mean: float
    entropy_std: float
    action_distribution: dict[str, float]
    n_samples: int

    def save(self, file_path: str | Path) -> None:
        p = Path(file_path)
        p.write_text(json.dumps(self.model_dump(), indent=2), encoding="utf-8")

    @classmethod
    def load(cls, file_path: str | Path) -> DriftBaseline:
        p = Path(file_path)
        data = json.loads(p.read_text(encoding="utf-8"))
        return cls.model_validate(data)


class DriftDetector:
    """Monitors three unsupervised signals: Input PSI, Policy Entropy, and Action Distribution."""

    def __init__(self, baseline: DriftBaseline):
        self.baseline = baseline

    @classmethod
    def fit_baseline(
        cls,
        episodes: list[EpisodeLog],
        feature_names: list[str],
        action_probs: list[list[float]] | None = None,
    ) -> DriftBaseline:
        """Computes baseline quantile boundaries, expected bucket frequencies, entropy, and action rates."""
        all_obs: list[list[float]] = []
        all_actions: list[int] = []

        for ep in episodes:
            for s in ep.steps:
                all_obs.append(s.obs_vector)
                act_idx = s.events.get("action", {}).get("action_idx", 0)
                all_actions.append(int(act_idx))

        obs_arr = np.array(all_obs, dtype=np.float32)
        n_samples, n_features = obs_arr.shape

        # 1. Quantile boundaries per feature (deciles: 0%, 10%, ..., 100%)
        deciles = np.linspace(0, 100, 11)
        quantiles_per_feature: dict[str, list[float]] = {}
        expected_proportions: dict[str, list[float]] = {}

        for f_idx, fname in enumerate(feature_names[:n_features]):
            col = obs_arr[:, f_idx]
            edges = np.unique(np.percentile(col, deciles))
            if len(edges) >= 3:
                bin_edges = np.copy(edges)
                bin_edges[0] = -np.inf
                bin_edges[-1] = np.inf
                counts, _ = np.histogram(col, bins=bin_edges)
                q_props = (counts / max(1, n_samples)).tolist()
                quantiles_per_feature[fname] = edges.tolist()
                expected_proportions[fname] = q_props

        # 2. Entropy distribution
        if action_probs is not None and len(action_probs) > 0:
            p_arr = np.array(action_probs, dtype=np.float32)
            ent_vals = -np.sum(p_arr * np.log(np.maximum(p_arr, 1e-8)), axis=-1)
            entropy_mean = float(np.mean(ent_vals))
            entropy_std = float(max(np.std(ent_vals), 0.05))
        else:
            entropy_mean = 0.25
            entropy_std = 0.08

        # 3. Baseline action distribution
        action_dist: dict[str, float] = {}
        unique_acts, counts = np.unique(all_actions, return_counts=True)
        for act, cnt in zip(unique_acts, counts):
            action_dist[str(int(act))] = float(cnt / n_samples)

        return DriftBaseline(
            feature_names=feature_names[:n_features],
            quantiles_per_feature=quantiles_per_feature,
            expected_proportions=expected_proportions,
            entropy_mean=entropy_mean,
            entropy_std=entropy_std,
            action_distribution=action_dist,
            n_samples=n_samples,
        )

    def check_drift(
        self,
        obs_batch: np.ndarray | list[list[float]],
        action_probs_batch: np.ndarray | list[list[float]],
    ) -> DriftReport:
        """Inspects live batch for Population Stability Index, entropy shifts, and action rate shifts."""
        obs_arr = np.array(obs_batch, dtype=np.float32)
        probs_arr = np.array(action_probs_batch, dtype=np.float32)
        n_samples = len(obs_arr)

        reasons: list[str] = []
        is_drifted = False

        # 1. Input Feature PSI: sum((P_i - Q_i) * ln(P_i / Q_i))
        psi_per_feature: dict[str, float] = {}
        eps = 1e-4

        for f_idx, fname in enumerate(self.baseline.feature_names):
            if f_idx >= obs_arr.shape[1]:
                continue
            if fname not in self.baseline.quantiles_per_feature:
                continue

            edges = np.array(self.baseline.quantiles_per_feature[fname])
            q_expected = np.array(self.baseline.expected_proportions.get(fname, []))
            if len(edges) < 3 or len(q_expected) != (len(edges) - 1):
                continue

            col = obs_arr[:, f_idx]
            bin_edges = np.copy(edges)
            bin_edges[0] = -np.inf
            bin_edges[-1] = np.inf

            counts, _ = np.histogram(col, bins=bin_edges)
            proportions = np.maximum(counts / max(1, n_samples), eps)
            proportions = proportions / np.sum(proportions)

            q_smoothed = np.maximum(q_expected, eps)
            q_smoothed = q_smoothed / np.sum(q_smoothed)

            psi = float(np.sum((proportions - q_smoothed) * np.log(proportions / q_smoothed)))
            psi_per_feature[fname] = psi

        max_psi = max(psi_per_feature.values()) if psi_per_feature else 0.0
        if max_psi > 0.25:
            is_drifted = True
            high_features = [k for k, v in psi_per_feature.items() if v > 0.25]
            reasons.append(f"Input PSI drift detected on {high_features} (max PSI: {max_psi:.3f} > 0.25)")

        # 2. Entropy Shift: rolling mean entropy shifts by > 2.5 sigma
        ent_vals = -np.sum(probs_arr * np.log(np.maximum(probs_arr, 1e-8)), axis=-1)
        mean_entropy = float(np.mean(ent_vals))
        entropy_zscore = float(abs(mean_entropy - self.baseline.entropy_mean) / max(self.baseline.entropy_std, 1e-4))

        if entropy_zscore > 2.5:
            is_drifted = True
            reasons.append(f"Policy entropy uncertainty drift (Z-score: {entropy_zscore:.2f} > 2.5)")

        # 3. Action-Rate Distribution Shift: Z-score > 3.0
        pred_actions = np.argmax(probs_arr, axis=-1)
        current_action_dist: dict[str, float] = {}
        max_action_shift_zscore = 0.0

        for act_str, base_rate in self.baseline.action_distribution.items():
            act_int = int(act_str)
            live_count = np.sum(pred_actions == act_int)
            live_rate = float(live_count / max(1, n_samples))
            current_action_dist[act_str] = live_rate

            std_err = np.sqrt(max(base_rate * (1.0 - base_rate), 1e-4) / max(1, n_samples))
            z_score = float(abs(live_rate - base_rate) / max(std_err, 1e-4))
            max_action_shift_zscore = max(max_action_shift_zscore, z_score)

        if max_action_shift_zscore > 3.0:
            is_drifted = True
            reasons.append(f"Action rate distribution shift (Z-score: {max_action_shift_zscore:.2f} > 3.0)")

        recommendation = (
            f"Drift alert: {'; '.join(reasons)}. Retrain policy recommended."
            if is_drifted
            else "Policy confident, no drift detected."
        )

        return DriftReport(
            is_drifted=is_drifted,
            max_psi=max_psi,
            psi_per_feature=psi_per_feature,
            entropy_zscore=entropy_zscore,
            current_entropy=mean_entropy,
            action_shift_zscore=max_action_shift_zscore,
            current_action_dist=current_action_dist,
            reasons=reasons,
            recommendation=recommendation,
        )
